{
  "name": "管式炉",
  "name_en": "Tube Furnace",
  "manufacturer": "",
  "description": "管式炉是一种用于对管内样品或气氛进行受控加热的高温实验设备，常用于材料退火、烧结、热处理以及高温反应实验。该设备可设定目标温度并读取当前炉温。",
  "description_en": "A tube furnace is a high-temperature laboratory instrument used to heat samples or process atmospheres inside a tube under controlled conditions. It is commonly used for annealing, sintering, heat treatment, and high-temperature reaction experiments. The device supports setting a target temperature and reading the current furnace temperature.",
  "tag_hints": [
    "tube furnace",
    "high-temperature heating",
    "thermal treatment",
    "annealing",
    "sintering",
    "temperature control",
    "high-temperature reaction"
  ],
  "actions": [
    {
      "action_name": "auto-SetTemp",
      "description": "设置炉温设定值",
      "description_en": "Set the furnace temperature setpoint"
    },
    {
      "action_name": "auto-QueryTemp",
      "description": "获取当前炉温",
      "description_en": "Get the current furnace temperature"
    },
    {
      "action_name": "auto-ChangeAddress",
      "description": "设置通信地址",
      "description_en": "Set the communication address"
    },
    {
      "action_name": "auto-ReportStatus",
      "description": "报告设备状态",
      "description_en": "Report the device status"
    }
  ]
}

